(function () {
  "use strict";

  var KEY = "das.lang";
  var I18N = {"en":{"shared.nav.home":"Home","shared.nav.arch":"Architecture","shared.nav.road":"Roadmap","shared.nav.start":"Get Started","shared.nav.github":"GitHub","shared.skip":"Skip to content","shared.status.verified":"Verified","shared.status.partial":"Partial","shared.status.prototype":"Prototype","shared.table.package":"Package","shared.table.role":"Role","shared.table.tools":"Tools","shared.table.status":"Status","shared.cta.arch.k":"Architecture","shared.cta.arch.t":"Why it's built this way","shared.cta.road.k":"Roadmap","shared.cta.road.t":"Can I use it now?","shared.cta.start.k":"Get Started","shared.cta.start.t":"Run it in one command","shared.copy":"Copy","shared.copied":"Copied","shared.footer.disclaimer":"Unofficial project. Not affiliated with DeepSeek or Siemens. TIA Portal and SIMATIC are trademarks of Siemens AG, named here for reference only.","shared.footer.source":"GitHub","shared.footer.license":"MIT","shared.footer.updated":"Last checked 2026-11-08","meta.home.title":"dsh-automation-suite — agent tool for PLC programming","meta.home.desc":"An unofficial DeepSeek Harness distribution that integrates the Siemens TIA Openness toolkit: TIA Portal V17 block access, an engineering knowledge graph and guard-railed Git.","meta.arch.title":"Architecture — dsh-automation-suite","meta.arch.desc":"How twelve bundles become one DSH distribution: package boundaries, runtime service seams, and preset-scoped tools.","meta.road.title":"Roadmap — dsh-automation-suite","meta.road.desc":"Maturity, environment compatibility and the planned capability of the distribution.","meta.start.title":"Get Started — dsh-automation-suite","meta.start.desc":"One command to a running DSH instance with the automation suite's plugins.","home.hero.title":"\r\n                        <span class=\"\"> Your Automation </span>\r\n                        <br />\r\n                        <span class=\"tw-font-thin tw-font-serif\"> Programming Copilot </span>\r\n                    ","home.hero.lead":"Put engineering effort where it counts.<br />Leave the rest to your AI partner.","road.head.eyebrow":"Roadmap","road.head.title":"Where it stands today","road.head.lead":"An early build. Statuses follow the repository roadmap, and nothing planned is presented as shipped.","road.m.title":"Maturity","road.m.note":"The three layers, as they actually are.","road.m1.title":"Access","road.m1.desc":"Block export and import, compile and project data work on real projects. Twenty operations added in v0.2 are still unverified in the field.","road.m2.title":"Semantics","road.m2.desc":"XML to SQLite graph works on fixtures. Freshness, incremental updates and a compatibility layer are not done.","road.m3.title":"Governance","road.m3.desc":"The Git tools are general-purpose. The version workflow is two steps: sync the source tree, then commit it.","road.env.title":"Compatibility","road.env.note":"What it runs on today.","road.env.os.label":"Operating system","road.env.os.value":"Windows for the TIA tools. Other platforms can load the plugins, but TIA calls fail.","road.env.dsh.label":"DeepSeek Harness","road.env.dsh.value":"Any version that can load bundles; built and tested against 0.2.1-rc.2.","road.env.tia.label":"TIA Portal","road.env.tia.value":"V17 only — V16 and V18 are not compatible.","road.env.node.label":"Node.js","road.env.node.value":"22.19 or newer.","road.env.openness.label":"Openness","road.env.openness.value":"Siemens.Engineering.dll from Portal V17, and membership in the local “Siemens TIA Openness” group.","road.next.title":"Next","road.next.note":"Planned, not promised.","road.n1.title":"V18 member","road.n1.desc":"A second interface-plugin member, sharing the same core.","road.n2.title":"More capability","road.n2.desc":"Hardware configuration, online and download, comparison and libraries.","road.n3.title":"Graph freshness","road.n3.desc":"Incremental updates and a compatibility layer for older exports.","road.n4.title":"Change ledger","road.n4.desc":"A per-block change ledger, with DRAFT and REMOTE workspace states.","road.link":"Full roadmap and open questions","start.head.eyebrow":"Get started","start.head.title":"Install it, start it, verify it","start.head.lead":"One setup for most people: the desktop app. Three alternates for special cases — the release zip, the repository starter, or a single bundle. All run the same blueprint in an isolated DSH_HOME.","start.req.note":"The suite runs on DSH. The desktop setup installs what is missing; only the TIA and PLCSIM tools need Siemens software.","start.req.os.label":"Operating system","start.req.os.value":"Windows 10/11 x64 for the desktop shell and all TIA/PLCSIM work. The non-TIA plugins can load on other platforms, but this guide assumes Windows.","start.req.dsh.label":"DeepSeek Harness","start.req.dsh.value":"The desktop setup reuses an installed DSH (≥ 0.2.1-rc.1; verified against 0.2.1-rc.2) and downloads the official runtime when it is missing. The zip and single-bundle paths expect it preinstalled.","start.req.tia.label":"TIA Portal V17","start.req.tia.value":"Only for the TIA tools: V17 with Openness — V16 and V18 are not compatible; TIA also brings the .NET Framework 4.8 runtime the controllers use. Requires Siemens.Engineering.dll under PublicAPI\\V17 and the current user in the local “Siemens TIA Openness” group.","start.req.plcsim.label":"PLCSIM Advanced","start.req.plcsim.value":"Optional; only for the simulation tools. Needs PLCSIM Advanced with API 4.0 (4.0–7.0 runtimes work).","start.req.git.label":"Git CLI","start.req.git.value":"Only for the git tools. DSH does not bundle git; run <code>git --version</code>, or install Git for Windows.","start.req.note2":"Excel and PDF support is pure JavaScript/WASM — no Microsoft Office or Acrobat install. The only desktop software this suite calls is TIA Portal, PLCSIM Advanced and Git.","start.install.title":"Other install paths","start.install.note":"Same blueprint, different packaging. Use these when you cannot run an installer, want the current worktree, or need a single bundle.","start.install.a.title":"Release zip","start.install.a.desc":"No build, no Node; installs into a versioned profile under <code>%USERPROFILE%\\dsh-automation-suite-home</code> and starts DSH from a console. Needs an installed DSH.","start.install.b.title":"From source","start.install.b.desc":"For development. Runs the current worktree; needs Node 22.19+ and the pnpm bundled with DSH; <code>-Mode pack</code> tests the real tarballs.","start.install.c.title":"One plugin only","start.install.c.desc":"Advanced. Every package is its own bundle; install its tarball and add the matching <code>/tools</code> row when it has one.","start.install.a.h":"A · Release zip","start.install.a.note":"Download <code>dsh-automation-suite-&lt;version&gt;.zip</code> from Releases and extract it first. Double-clicking the two <code>.cmd</code> files works too; <code>install.cmd</code> avoids the PowerShell execution-policy block on downloaded scripts.","start.install.b.h":"B · From source","start.install.b.note":"The starter builds the packages, materializes the profile in <code>%USERPROFILE%\\dsh-automation-suite-home</code>, links the local packages, starts <code>dsh</code> and opens the tokenized URL. Use <code>-Mode pack</code> to test the release tarballs and <code>-Restart</code> to replace a running instance.","start.install.c.h":"C · One plugin only","start.install.c.note":"TIA, PLCSIM, graph and git expose model tools only after a <code>/tools</code> row is added; engineering-context also needs TIA and git at runtime. This path is for advanced users — the <a href=\"../architecture/\">Architecture</a> page has the surface matrix.","start.install.dshnote":"These three paths assume DeepSeek Harness is already installed: the zip installer exits with an error if it cannot find <code>dsh.cmd</code>. Only the desktop setup can fetch the runtime for you.","start.config.title":"First start","start.config.note":"From an opened window to a working session.","start.s1.title":"Open the window — or the printed URL","start.s1.desc":"The desktop shell starts DSH for you and loads the tokenized URL into its own window; the zip path prints <code>dsh web: http://127.0.0.1:&lt;port&gt;/?token=…</code> in the console instead. Either way the token is required and changes on every start — the bare port returns 401, so do not share the URL.","start.s2.title":"Add a model API key","start.s2.desc":"Settings → Models, or the first-run prompt. The release profile defaults to <code>dsh-opencode-go</code> / <code>deepseek-v4.1-flash</code>; add that provider's key or pick another model. Credentials stay in this DSH_HOME.","start.s3.title":"Add a workspace","start.s3.desc":"Point at the project folder. The left sidebar is a registry stored in DSH_HOME, not a scan of the disk, so every workspace is added explicitly; since 0.2.3 the picker is the app's own directory surface, not the Windows folder dialog.","start.s4.title":"Verify the engineering path","start.s4.desc":"TIA: open or create a project and make a read-only call. Graph: <code>create_engineering_project</code> should report a built database; “not built” often means .NET 8 is missing — install Microsoft.DotNet.Runtime.8. Git: run <code>git --version</code>.","start.s5.title":"Quit from the menu, not the X","start.s5.desc":"The window's close button hides it to the tray and the app — TIA controller included — keeps running; use <code>Application → Exit</code> or the tray's Exit to stop everything. On the zip path, closing the console stops the service and <code>start.cmd</code> starts it again. Sessions, workspaces and credentials persist either way.","start.config.timeout.title":"Large projects and long calls","start.config.timeout.desc":"The default <code>requestTimeoutMs</code> is 300000 (5 minutes). Exporting a few hundred blocks already takes about 87 s, and compiling a large project can take more than 10 minutes. Raise it in the profile patch (or the matching settings row) before the first large TIA or graph call.","start.config.timeout.note":"The same value bounds a single-device graph build; a 1,376-file project took about 30 s, but large projects deserve the headroom.","start.notes.title":"Installation notes","start.notes.note":"The things that most often go wrong, and the safe way to undo.","start.notes.th.topic":"Topic","start.notes.th.note":"What to know","start.notes.n1.t":"DSH runtime","start.notes.n1.d":"The desktop setup reuses an installed DSH at or above 0.2.1-rc.1 and downloads the official runtime when it is missing, checking SHA-512 and the DeepSeek signature. The zip installer only finds an existing <code>dsh.cmd</code> (or <code>DSH_EXE</code>).","start.notes.n2.t":"SmartScreen","start.notes.n2.d":"Neither the setup exe nor the zip scripts are signed. For the setup: <strong>More info → Run anyway</strong>. For the scripts, use <code>install.cmd</code> / <code>start.cmd</code> (they set a process-level bypass and pause on errors); running <code>install.ps1</code> directly may close before you can read the error.","start.notes.n3.t":"Two roots","start.notes.n3.d":"Desktop: app files in <code>%LOCALAPPDATA%\\dsh-automation-suite</code>, user data in <code>%USERPROFILE%\\dsh-automation-suite-home</code> with the fixed profile name <code>dsh-automation-suite</code>. The zip path uses the same home with a versioned profile. Nothing is written to <code>~/.dsh</code>.","start.notes.n4.t":"Upgrade / rollback","start.notes.n4.d":"Desktop: exit the app, then run the next setup over the old one — the shell is replaced, the app layer gets a new versioned folder, and the fixed profile's <code>cordis.patch.yml</code> overrides are backed up as <code>.bak-&lt;timestamp&gt;</code> and merged. Web zip: each version gets its own profile, so start the older one to roll back.","start.notes.n5.t":"Uninstall","start.notes.n5.d":"Desktop: Windows Settings → Apps → DSH Automation Suite removes the shell, the app layers and the shortcuts; <code>dsh-automation-suite-home</code> is kept. Delete user data with <code>cmd /c rmdir /s /q \"%USERPROFILE%\\dsh-automation-suite-home\"</code>; never use a recursive delete that follows junctions.","start.notes.n6.t":"External runtimes","start.notes.n6.d":"The shell needs Evergreen WebView2 (the setup installs the bootstrapper when it is missing). Only TIA and PLCSIM need Siemens software. The graph needs .NET 8; git needs <code>git.exe</code>; Excel/PDF need no Office or Acrobat. TIA and PLCSIM licensing is yours.","start.notes.n7.t":"Network / proxy","start.notes.n7.d":"The desktop setup needs GitHub for the download and <code>download.deepseek.com</code> for DSH/WebView2 when they are missing — never npm, because the profile ships materialized. The zip path needs GitHub and npm; on an isolated network, mirror the registry or pre-stage the tarballs.","start.notes.n8.t":"Ports","start.notes.n8.d":"The shell starts DSH with an OS-assigned free port (<code>--port 0</code>), so there is nothing to configure — the window loads whatever port was picked. The zip path's <code>start.cmd</code> picks 3093+ automatically instead; it also accepts <code>-Port</code>, and <code>-NoOpen</code> suppresses the browser.","start.notes.n9.t":"Desktop shell","start.notes.n9.d":"0.2.3 ships the WebView2 shell and the per-user installer: Start-menu entry, optional desktop shortcut, tray, single instance, logs reachable from the tray's <em>Open logs</em>. There is still no auto-update — upgrade by running the next setup.","start.notes.n10.t":"Security","start.notes.n10.d":"Treat the tokenized URL as a secret; it grants the session. Keep DSH_HOME out of source control — credentials and sessions live there.","start.link.releases":"Releases","start.link":"Repository README","start.req.title":"Before you start","start.desktop.title":"Install the desktop app","start.desktop.note":"Recommended since 0.2.3: one setup exe, per-user, no Node, no console window. The wizard installs the WebView2 shell, a pre-built profile and the doctor, and downloads DeepSeek Harness and WebView2 first if either is missing.","start.desktop.s1.title":"Run the setup","start.desktop.s1.desc":"Download <code>dsh-automation-suite-setup-&lt;version&gt;.exe</code> from <a href=\"https://github.com/voltarenyah/dsh-automation-suite/releases\">Releases</a> and run it. The binary is not code-signed, so Windows stops it once with the SmartScreen dialog below — “Unknown publisher” is expected here, not a sign of tampering.","start.desktop.s1.cap":"SmartScreen before “More info” — the only visible button is “Don’t run”.","start.desktop.s2.title":"Allow it through SmartScreen","start.desktop.s2.desc":"Click <strong>More info</strong>, check that the app is <code>dsh-automation-suite-setup-&lt;version&gt;.exe</code> with publisher “Unknown publisher”, then click <strong>Run anyway</strong>. If you want certainty first, compare the published SHA-256 with <code>Get-FileHash</code>.","start.desktop.s2.cap":"After “More info”: the file name, the publisher, and “Run anyway”.","start.desktop.s3.title":"Welcome page","start.desktop.s3.desc":"The wizard names the version it is about to install and asks you to close other applications. Nothing has been written yet; the close button leaves the machine untouched.","start.desktop.s3.cap":"Setup - DSH Automation Suite, version 0.2.3.","start.desktop.s4.title":"Destination folder","start.desktop.s4.desc":"The default is <code>%LOCALAPPDATA%\\dsh-automation-suite</code> — per-user, no administrator rights, removable through Windows Settings. The profile ships with its <code>node_modules</code> already materialized, so setup needs about 218 MB; the stable shell, the versioned app layer, <code>install.json</code> and the uninstaller all live here.","start.desktop.s4.cap":"Destination: <code>%LOCALAPPDATA%\\dsh-automation-suite</code>, at least 217.8 MB free.","start.desktop.s5.title":"Additional tasks","start.desktop.s5.desc":"A desktop shortcut is the only optional task; the Start-menu entry is always created. <strong>Next</strong> starts the copy. If DSH or WebView2 is missing, the wizard then runs a PowerShell step that downloads the official package (DSH is about 300 MB) and verifies its SHA-512 and DeepSeek signature before installing it — that is the only part that needs a network. Afterwards it copies the fixed profile into <code>dsh-automation-suite-home</code>, merges any older overrides and runs <code>doctor</code>.","start.desktop.s5.cap":"Additional icons: create a desktop shortcut (optional).","start.desktop.s6.title":"Finish and launch","start.desktop.s6.desc":"Leave <strong>Launch DSH Automation Suite</strong> checked and click <strong>Finish</strong>. The app window opens with the suite profile already active — there is no console window to keep open.","start.desktop.s6.cap":"Completing the wizard — uncheck the launch box to only install the shortcuts.","start.desktop.s7.title":"What opens","start.desktop.s7.desc":"A WebView2 window with the same 40 px title bar as the DeepSeek Harness desktop app — <code>Application</code> and <code>Edit</code> menus on the left, window buttons on the right, the suite preset and its five right-hand tabs already loaded. There is no address bar and the shell never depends on your browser. Theme and language follow the app's own settings, as the two thumbnails below show.","start.desktop.s7.cap":"The shell after setup: light theme, English UI.","start.desktop.s7.cap2":"Dark theme, English UI.","start.desktop.s7.cap3":"Dark theme, 中文 UI.","start.desktop.callout":"The setup never bundles the DSH runtime: it reuses what you have, or fetches the official package from <code>download.deepseek.com</code>. A DSH newer than the verified 0.2.1-rc.2 is allowed after a warning; one older than 0.2.1-rc.1 is refused rather than overwritten. On an offline machine, install DSH and WebView2 first — after that the wizard works without a network, because nothing is fetched from npm.","start.desktop.s8.title":"Working in it","start.desktop.s8.desc":"A session in progress: the model runs the TIA tools one by one (<code>project_status</code>, <code>workspace_describe</code>, <code>open_project</code>, <code>project_version_query</code>, <code>git_status</code>), the chat shows its planning and the to-do list, and the <strong>Versions</strong> panel renders the last two commits with every changed block and whether the change touched the interface, the code, the comments or the block properties. This is the shipped UI, not a mockup.","start.desktop.s8.cap":"A running session — tool calls, to-dos and the Versions panel in the dark shell.","start.openness.title":"First TIA call: allow Openness access","start.openness.desc":"The first tool call that touches TIA is gated by Portal itself: “Openness access (0033:…)” asks whether <code>TiaOpennessV17Min.Controller.exe</code> — the controller under the profile's <code>node_modules</code> — may attach to the running instance. That dialog is Siemens', not the suite's, and there is no silent bypass. <strong>Yes</strong> grants the current session only; <strong>Yes to all</strong> also saves the authorization in the V17 whitelist (<code>HKLM\\SOFTWARE\\Siemens\\Automation\\Openness\\17.0\\Whitelist</code>), which is what stops the prompt coming back after a rebuild or an upgrade — writing it needs an elevated TIA. <strong>No</strong> makes the call fail: retry and allow it.","start.openness.cap":"Openness access — the suite's controller asking the running Portal for permission (open the full window).","home.nav.home":"Home","home.nav.arch":"Architecture","home.nav.road":"Roadmap","home.nav.start":"Get Started","home.hero.cta":"Get started","home.wall.eyebrow":"Capability map","home.wall.hint":"hover a term","home.wall.legend":"on the roadmap, not shipped yet","home.dist.title":"\r\n                    \r\n                    <span class=\"tw-font-semibold\">A DeepSeek Harness distribution built for industrial automation</span>\r\n                    <br>\r\n                    <span class=\"tw-font-serif\">Feel free to customize it with <span style=\"white-space: nowrap\">your own plugins</span>.</span>\r\n                ","home.dist.lead":"\r\n                    It bundles a set of core plugins that extend the agent with industrial-automation capabilities &mdash; TIA Portal access, an engineering knowledge graph, Git and PLCSIM.\r\n                ","home.dist.cta":"See Architecture","home.ctx.title":"\r\n                        Collaborate with AI\r\n                    ","home.ctx.note":"Know your project, help with your work. ","home.ctx.c1.title":"Project comprehension","home.ctx.c1.desc":"\r\n                                    Blocks exported, cross-references rebuilt, program sections translated,\r\n                                    drawings indexed — so the agent knows how the project fits together, and\r\n                                    answers questions based on necessary context.\r\n                                ","home.ctx.c2.title":"Version control","home.ctx.c2.desc":"\r\n                                    Block fingerprints show which blocks actually changed. The agent reads that against\r\n                                    the change context and makes the commit for you, keeping the version history\r\n                                    continuous instead of a pile of binary files.\r\n                                ","home.ctx.c3.title":"Simulation","home.ctx.c3.desc":"\r\n                                    PLCSIM Advanced is wired in through its API 4.0 — power on and off, download, tag\r\n                                    read and write, snapshot and restore — so the agent can exercise the program and\r\n                                    judge how it really behaves, not only what the source says.\r\n                                ","home.ctx.wide.caption":"Also in reach","home.ctx.chip1":"Electrical drawings","home.ctx.chip2":"Change history","home.ctx.chip3":"Technical docs","home.ctx.chip4":"Hardware config","home.ctx.chip5":"Installed skills","home.ctx.wide.title":"The wider engineering context","home.ctx.wide.desc":"\r\n                                    A PLC project is more than its program. Once the drawings, change history,\r\n                                    documents and hardware around it are in reach, the agent works from the\r\n                                    project's real background — and can answer how things came to be, not only\r\n                                    what the code says today.\r\n                                ","home.ships.title":"\r\n                            What ships today\r\n                        ","home.ships.note":"\r\n                            Six families, one profile. Statuses follow the repository roadmap —\r\n                            nothing planned is presented as shipped.\r\n                        ","home.ships.cta":"See the components","home.ships.s1.title":"\r\n                                    TIA Portal V17 access\r\n                                ","home.ships.s1.desc":"\r\n                                    Blocks, tags and project data through TIA Openness — 46 tools, one whitelisted\r\n                                    operation per tool, dry-run where it matters and read-back after every write.\r\n                                ","home.ships.s1.status":"Partial","home.ships.s2.title":"\r\n                                    Engineering knowledge graph\r\n                                ","home.ships.s2.desc":"\r\n                                    Exported sources become a queryable graph — blocks, calls, tags and I/O per\r\n                                    device — so “who calls this block” is a query, not a grep.\r\n                                ","home.ships.s2.status":"Prototype","home.ships.s3.title":"\r\n                                    Guard-railed Git\r\n                                ","home.ships.s3.desc":"\r\n                                    Twelve Git tools with the destructive ones behind an explicit policy: the agent\r\n                                    can diff, commit and trace, but cannot quietly rewrite history.\r\n                                ","home.ships.s3.status":"Partial","home.ships.s4.title":"\r\n                                    Simulation\r\n                                ","home.ships.s4.desc":"\r\n                                    PLCSIM Advanced over its API 4.0: power on and off, RUN / STOP / reset, tag read\r\n                                    and write, snapshot and restore.\r\n                                ","home.ships.s4.status":"Prototype","home.ships.s5.title":"\r\n                                    Panels in the app\r\n                                ","home.ships.s5.desc":"\r\n                                    PLC blocks, Versions, Changes, Hardware and Drawings docked next to the chat —\r\n                                    the same state the model reads, on screen where you can check it.\r\n                                ","home.ships.s5.status":"Partial","home.ships.s6.title":"\r\n                                    What comes next\r\n                                ","home.ships.s6.desc":"\r\n                                    TIA Portal V18, hardware configuration, online &amp; download, block\r\n                                    comparison, cable &amp; terminal drawings — planned, not promised.\r\n                                ","home.ships.s6.status":"Roadmap","home.faq.title":"\r\n                FAQ\r\n            ","home.faq.q1":"Is this an official DeepSeek or Siemens product?","home.faq.a1":"\r\n                        No. It is an unofficial DeepSeek Harness distribution plus our own TIA and engineering\r\n                        plugins. DeepSeek, Siemens and TIA Portal are named for reference only; the MIT license\r\n                        covers this repository, and TIA Portal / PLCSIM licensing stays with you.\r\n                    ","home.faq.q2":"What do I need to run it?","home.faq.a2":"\r\n                        Windows 10/11 x64 and DeepSeek Harness — the desktop setup fetches DSH if it is missing.\r\n                        The TIA tools need TIA Portal V17 with Openness, simulation needs PLCSIM Advanced with\r\n                        API 4.0, and the knowledge graph needs .NET 8.\r\n                    ","home.faq.q3":"Does it write into my project on its own?","home.faq.a3":"\r\n                        No. Reads are explicit calls; writes are tool calls with dry-run where it matters, run\r\n                        inside a TIA transaction and read back before they are reported as done. If verification\r\n                        fails, the transaction rolls back and the project is left as it was.\r\n                    ","home.faq.q4":"How are changes versioned?","home.faq.a4":"\r\n                        The project source is exported to text and committed to Git. The Versions panel reads the\r\n                        last commits, lists per-block changes and their kind — interface, code, comments,\r\n                        properties — so a change is reviewable instead of a binary blob.\r\n                    ","home.faq.q5":"Does it need the cloud?","home.faq.a5":"\r\n                        It runs locally: shell, plugins and the TIA controller are all on your machine. The only\r\n                        outbound traffic is the model API you configure, plus GitHub and download.deepseek.com\r\n                        while installing.\r\n                    ","home.faq.q6":"What is not there yet?","home.faq.a6":"\r\n                        V18 support, hardware configuration, online &amp; download, block comparison and\r\n                        cable/terminal drawings. The Roadmap page gives the honest status of each.\r\n                    ","home.end.title":"\r\n                    Install it and open a project\r\n                ","home.end.note":"\r\n                    One setup, a private DSH home, no build step. The TIA tools are ready once Portal V17\r\n                    is installed.\r\n                ","home.end.cta":"Get started","home.end.cta2":"Read the architecture","home.foot.product":"Product","home.foot.arch":"Architecture","home.foot.road":"Roadmap","home.foot.start":"Get started","home.foot.releases":"Releases","home.foot.repo":"Repository","home.foot.github":"GitHub","home.foot.readme":"README","home.foot.license":"MIT license","home.foot.notes":"Notes","home.foot.disclaimer":"Unofficial project. Not affiliated with DeepSeek or Siemens.","home.foot.trademark":"TIA Portal and SIMATIC are trademarks of Siemens AG, named here for reference only.","home.foot.copy":"© 2026 dsh-automation-suite · MIT","home.foot.checked":"Last checked 2026-11-09"},"zh":{"shared.nav.home":"首页","shared.nav.arch":"架构","shared.nav.road":"路线图","shared.nav.start":"开始使用","shared.nav.github":"GitHub","shared.skip":"跳到正文","shared.status.verified":"已验证","shared.status.partial":"部分实现","shared.status.prototype":"原型","shared.table.package":"包","shared.table.role":"职责","shared.table.tools":"工具","shared.table.status":"状态","shared.cta.arch.k":"架构","shared.cta.arch.t":"它凭什么可信","shared.cta.road.k":"路线图","shared.cta.road.t":"现在能不能用","shared.cta.start.k":"开始使用","shared.cta.start.t":"一条命令跑起来","shared.copy":"复制","shared.copied":"已复制","shared.footer.disclaimer":"非官方项目，与 DeepSeek 及 Siemens 均无隶属关系。TIA Portal 与 SIMATIC 是 Siemens AG 的商标，此处仅作事实性指称。","shared.footer.source":"GitHub","shared.footer.license":"MIT","shared.footer.updated":"最后核对 2026-11-08","meta.home.title":"dsh-automation-suite — 面向 PLC 编程的 Agent 工具","meta.home.desc":"非官方 DeepSeek Harness 发行版，集成 Siemens TIA Openness 工具链：TIA Portal V17 块级读写、工程知识图谱与受控 Git。","meta.arch.title":"架构 — dsh-automation-suite","meta.arch.desc":"十二个 bundle 如何组成一个 DSH 发行版：包边界、运行时服务缝与 preset 工具面。","meta.road.title":"路线图 — dsh-automation-suite","meta.road.desc":"成熟度、环境兼容性与规划中的能力。","meta.start.title":"开始使用 — dsh-automation-suite","meta.start.desc":"一条命令启动带自动化套件插件的 DSH 实例。","home.hero.title":"<span class=\"\"> 你的自动化 </span>\n                        <br />\n                        <span class=\"tw-font-thin tw-font-serif\"> 编程 Copilot </span>","home.hero.lead":"把工程精力放在真正重要的地方，<br />其余交给你的 AI 伙伴。","road.head.eyebrow":"路线图","road.head.title":"今天站在哪里","road.head.lead":"早期版本。状态以仓库路线图为准，规划中的能力不会被写成已实现。","road.m.title":"成熟度","road.m.note":"三层能力目前的真实状态。","road.m1.title":"接入层","road.m1.desc":"块导入导出、编译与工程数据已在真实项目上跑通；v0.2 新增的 20 个操作尚未真机验证。","road.m2.title":"语义层","road.m2.desc":"XML → SQLite 图谱已在样例上跑通；新鲜度、增量与兼容层未做。","road.m3.title":"管理与协作层","road.m3.desc":"Git 工具是通用底座；版本流程是「同步」与「提交」两步。","road.env.title":"环境兼容性","road.env.note":"今天能在什么环境里跑。","road.env.os.label":"操作系统","road.env.os.value":"TIA 工具仅 Windows；其它平台可加载插件，但 TIA 调用会失败。","road.env.dsh.label":"DeepSeek Harness","road.env.dsh.value":"任何能加载 bundle 的版本；按 0.2.1-rc.2 构建与测试。","road.env.tia.label":"TIA Portal","road.env.tia.value":"仅 V17 —— 不兼容 V16 / V18。","road.env.node.label":"Node.js","road.env.node.value":"22.19 或更新。","road.env.openness.label":"Openness","road.env.openness.value":"Portal V17 的 Siemens.Engineering.dll，且当前用户在本地「Siemens TIA Openness」组内。","road.next.title":"下一步","road.next.note":"规划，不是承诺。","road.n1.title":"V18 成员","road.n1.desc":"第二个接口插件成员，共享同一内核。","road.n2.title":"更多能力","road.n2.desc":"硬件组态、在线下载、比较与库。","road.n3.title":"图谱新鲜度","road.n3.desc":"增量更新，以及面向旧导出物的兼容层。","road.n4.title":"变更台账","road.n4.desc":"逐块变更台账，以及 DRAFT / REMOTE 工作区状态。","road.link":"完整路线图与待决问题","start.head.eyebrow":"开始使用","start.head.title":"装好、启动、验证","start.head.lead":"多数人只有一条路：装桌面版。另有三条特殊路径 —— 发布 zip、仓库启动脚本，或只装一个 bundle。它们都在独立的 DSH_HOME 里运行同一份蓝图。","start.req.note":"套件运行在 DSH 上。桌面版安装器会补齐缺少的部分；只有 TIA 与 PLCSIM 工具需要西门子软件。","start.req.os.label":"操作系统","start.req.os.value":"桌面壳与所有 TIA/PLCSIM 工作都要求 Windows 10/11 x64。非 TIA 插件可在其它平台加载，但本指南按 Windows 说明。","start.req.dsh.label":"DeepSeek Harness","start.req.dsh.value":"桌面版会复用已安装的 DSH（≥ 0.2.1-rc.1，按 0.2.1-rc.2 验证），缺失时下载官方运行时。发布 zip 与单包安装要求预先装好 DSH。","start.req.tia.label":"TIA Portal V17","start.req.tia.value":"只影响 TIA 工具：V17 且启用 Openness —— 不兼容 V16 / V18；TIA 也会带来控制器使用的 .NET Framework 4.8 运行时。需要 PublicAPI\\V17 下的 Siemens.Engineering.dll，且当前用户在本地“Siemens TIA Openness”组内。","start.req.plcsim.label":"PLCSIM Advanced","start.req.plcsim.value":"可选，只影响仿真工具。需要带 API 4.0 的 PLCSIM Advanced（4.0–7.0 运行时可用）。","start.req.git.label":"Git CLI","start.req.git.value":"只影响 git 工具。DSH 不自带 git；先运行 <code>git --version</code>，或安装 Git for Windows。","start.req.note2":"Excel 与 PDF 能力是纯 JavaScript/WASM —— 不需要安装 Microsoft Office 或 Acrobat。套件真正调用的桌面软件只有 TIA Portal、PLCSIM Advanced 与 Git。","start.install.title":"其它安装方式","start.install.note":"同一份蓝图，不同的打包方式。装不了安装器、想跑当前工作树，或只需要一个 bundle 时用这些。","start.install.a.title":"发布 zip","start.install.a.desc":"不需要构建、不需要 Node；装进 <code>%USERPROFILE%\\dsh-automation-suite-home</code> 下的版本化 profile，并从控制台启动 DSH。要求已装 DSH。","start.install.b.title":"从源码","start.install.b.desc":"面向开发。运行当前工作树；需要 Node 22.19+ 与 DSH 自带的 pnpm；<code>-Mode pack</code> 可验证真实 tarball。","start.install.c.title":"只装一个插件","start.install.c.desc":"进阶用法。每个包都是独立 bundle；安装它的 tarball，并在有 <code>/tools</code> 行时补上对应行。","start.install.a.h":"A · 发布 zip","start.install.a.note":"先从 Releases 下载并解压 <code>dsh-automation-suite-&lt;version&gt;.zip</code>。也可以直接双击两个 <code>.cmd</code>；<code>install.cmd</code> 能避开下载脚本的 PowerShell 执行策略拦截。","start.install.b.h":"B · 从源码","start.install.b.note":"启动器会构建各包、在 <code>%USERPROFILE%\\dsh-automation-suite-home</code> 物化 profile、链入本地包、启动 <code>dsh</code> 并打开带 token 的地址。用 <code>-Mode pack</code> 验证发布 tarball，用 <code>-Restart</code> 替换正在运行的实例。","start.install.c.h":"C · 只装一个插件","start.install.c.note":"TIA、PLCSIM、图谱与 git 只有在补上 <code>/tools</code> 行之后才会暴露模型工具；engineering-context 还需要 TIA 与 git 服务。此路径面向进阶用户 —— 工具面矩阵见<a href='../architecture/'>架构</a>页。","start.install.dshnote":"这三条路径都假设 DeepSeek Harness 已安装：zip 安装器找不到 <code>dsh.cmd</code> 会直接报错退出。只有桌面版安装器会替你下载运行时。","start.config.title":"首次启动","start.config.note":"从打开窗口到进入可用会话。","start.s1.title":"打开窗口 —— 或打印出的地址","start.s1.desc":"桌面壳会替你启动 DSH，并把带 token 的地址载入自己的窗口；zip 路径则是在控制台打印 <code>dsh web: http://127.0.0.1:&lt;port&gt;/?token=…</code>。两种方式都必须带 token，且每次启动都会变 —— 裸端口返回 401，不要把地址转发给别人。","start.s2.title":"填写模型 API key","start.s2.desc":"设置 → Models，或首次运行弹窗。发布 profile 默认使用 <code>dsh-opencode-go</code> / <code>deepseek-v4.1-flash</code>；填该提供方的 key，或另选模型。凭据只留在当前 DSH_HOME。","start.s3.title":"添加 workspace","start.s3.desc":"指向工程目录。左侧 workspace 列表是 DSH_HOME 里的注册表，不是磁盘扫描，所以每个 workspace 都要显式添加；0.2.3 起用的是应用内的目录选择器，而不是 Windows 文件夹对话框。","start.s4.title":"验证工程链路","start.s4.desc":"TIA：打开或新建工程并做一次只读调用。图谱：<code>create_engineering_project</code> 应报告已建库；“未建成”通常意味着缺 .NET 8 —— 安装 Microsoft.DotNet.Runtime.8。Git：运行 <code>git --version</code>。","start.s5.title":"用菜单退出，而不是右上角的 ×","start.s5.desc":"窗口的关闭按钮只是把它收进托盘，应用（包括 TIA 控制器）仍在运行；要完全停止，用 <code>Application → Exit</code> 或托盘菜单的 Exit。zip 路径下关闭控制台即停止服务，再次运行 <code>start.cmd</code> 即可。两种方式下会话、workspace 与凭据都会保留。","start.config.timeout.title":"大工程与长调用","start.config.timeout.desc":"<code>requestTimeoutMs</code> 默认 300000（5 分钟）。导出几百个块已需约 87 秒，编译大工程常超过 10 分钟。首次大 TIA 或图谱调用前，在 profile patch（或对应设置行）里调大。","start.config.timeout.note":"同一个值也限制单设备图谱建库；1,376 个文件约 30 秒，但大工程应留足余量。","start.notes.title":"安装注意事项","start.notes.note":"最常出问题的地方，以及安全的回退方式。","start.notes.th.topic":"主题","start.notes.th.note":"注意事项","start.notes.n1.t":"DSH 运行时","start.notes.n1.d":"桌面版安装器会复用已安装的 DSH（≥ 0.2.1-rc.1），缺失时下载官方运行时并校验 SHA-512 与 DeepSeek 签名。zip 安装器只查找已存在的 <code>dsh.cmd</code>（或 <code>DSH_EXE</code>）。","start.notes.n2.t":"SmartScreen","start.notes.n2.d":"安装器 exe 与 zip 里的脚本都没有签名。安装器：点「更多信息 → 仍要运行」。脚本：请用 <code>install.cmd</code> / <code>start.cmd</code>（它们在进程级绕过执行策略，出错时会暂停）；直接运行 <code>install.ps1</code> 可能窗口一闪就关。","start.notes.n3.t":"两个根目录","start.notes.n3.d":"桌面版：程序文件在 <code>%LOCALAPPDATA%\\dsh-automation-suite</code>，用户数据在 <code>%USERPROFILE%\\dsh-automation-suite-home</code>，profile 名固定为 <code>dsh-automation-suite</code>。zip 路径用同一个 home，但 profile 带版本号。都不会写 <code>~/.dsh</code>。","start.notes.n4.t":"升级 / 回退","start.notes.n4.d":"桌面版：先退出应用，再用新版安装器覆盖安装 —— 壳会被替换，应用层进新的版本目录，固定 profile 的 <code>cordis.patch.yml</code> 覆盖项会备份成 <code>.bak-&lt;timestamp&gt;</code> 后合并。Web zip：每个版本各有独立 profile，回退时启动旧的那个即可。","start.notes.n5.t":"卸载","start.notes.n5.d":"桌面版：Windows 设置 → 应用 → DSH Automation Suite 会移除壳、各版本应用层与快捷方式，保留 <code>dsh-automation-suite-home</code>。要删用户数据用 <code>cmd /c rmdir /s /q \"%USERPROFILE%\\dsh-automation-suite-home\"</code>；不要用会跟进 junction 的递归删除。","start.notes.n6.t":"外部运行时","start.notes.n6.d":"壳需要 Evergreen WebView2（缺失时安装器会装 bootstrapper）。只有 TIA 与 PLCSIM 需要西门子软件。图谱需要 .NET 8；git 需要 <code>git.exe</code>；Excel/PDF 不需要 Office 或 Acrobat。TIA/PLCSIM 的许可证由你自行提供。","start.notes.n7.t":"网络 / 代理","start.notes.n7.d":"桌面版安装器需要访问 GitHub 下载安装包，以及 DSH/WebView2 缺失时的 <code>download.deepseek.com</code> —— 不需要 npm，因为 profile 里的依赖已经物化。zip 路径需要 GitHub 与 npm；隔离网络下请镜像 registry 或预置 tarball。","start.notes.n8.t":"端口","start.notes.n8.d":"壳会以 <code>--port 0</code> 让 DSH 使用系统分配的空闲端口，因此无需配置 —— 窗口会加载实际选中的端口。zip 路径的 <code>start.cmd</code> 会自动从 3093 起找端口，也接受 <code>-Port</code>，<code>-NoOpen</code> 可关闭自动开浏览器。","start.notes.n9.t":"桌面壳","start.notes.n9.d":"0.2.3 已发布 WebView2 壳与按用户安装的安装器：开始菜单项、可选的桌面快捷方式、托盘、单实例，日志可从托盘菜单的 <em>Open logs</em> 打开。目前仍无自动更新 —— 升级就是再跑一次新版安装器。","start.notes.n10.t":"安全","start.notes.n10.d":"把带 token 的地址当作密钥，它代表当前会话。不要把 DSH_HOME 提交进版本库 —— 凭据与会话都在里面。","start.link.releases":"Releases","start.link":"仓库 README","start.req.title":"开始之前","start.desktop.title":"安装桌面版","start.desktop.note":"0.2.3 起推荐这条路径：一个安装器、按用户安装、不需要 Node、不弹控制台窗口。向导会装好 WebView2 壳、预置 profile 与 doctor；缺 DeepSeek Harness 或 WebView2 时会先下载安装。","start.desktop.s1.title":"运行安装器","start.desktop.s1.desc":"从 <a href=\"https://github.com/voltarenyah/dsh-automation-suite/releases\">Releases</a> 下载 <code>dsh-automation-suite-setup-&lt;version&gt;.exe</code> 并运行。程序没有代码签名，所以 Windows 会先用下面的 SmartScreen 拦一次 —— 出现「未知发布者」是预期的，不代表文件被篡改。","start.desktop.s1.cap":"点「更多信息」之前的 SmartScreen —— 唯一可见的按钮是「不运行」。","start.desktop.s2.title":"通过 SmartScreen 放行","start.desktop.s2.desc":"点 <strong>More info</strong>，确认应用是 <code>dsh-automation-suite-setup-&lt;version&gt;.exe</code>、发布者为“Unknown publisher”，再点 <strong>Run anyway</strong>。想先确认完整性，可以用 <code>Get-FileHash</code> 与发布页的 SHA-256 比对。","start.desktop.s2.cap":"点开「更多信息」后：文件名、发布者，以及「仍要运行」。","start.desktop.s3.title":"欢迎页","start.desktop.s3.desc":"向导会说明要装的版本，并建议先关闭其它应用。此时还没有写入任何东西；直接关掉窗口不会改动系统。","start.desktop.s3.cap":"Setup - DSH Automation Suite，版本 0.2.3。","start.desktop.s4.title":"安装位置","start.desktop.s4.desc":"默认是 <code>%LOCALAPPDATA%\\dsh-automation-suite</code> —— 按当前用户安装、不需要管理员权限，可从 Windows 设置里卸载。profile 的 <code>node_modules</code> 已经物化，所以安装约需 218 MB；固定路径的壳、按版本分的应用层、<code>install.json</code> 与卸载器都在这里。","start.desktop.s4.cap":"安装位置：<code>%LOCALAPPDATA%\\dsh-automation-suite</code>，至少需要 217.8 MB 空闲空间。","start.desktop.s5.title":"附加任务","start.desktop.s5.desc":"唯一可选项是桌面快捷方式，开始菜单项总会创建。点 <strong>Next</strong> 开始复制；若缺 DSH 或 WebView2，向导随后会执行一段 PowerShell，下载官方安装包（DSH 约 300 MB）并校验 SHA-512 与 DeepSeek 签名后再安装 —— 这是全流程唯一需要联网的部分。之后它把固定 profile 复制进 <code>dsh-automation-suite-home</code>、合并旧覆盖项并跑 <code>doctor</code>。","start.desktop.s5.cap":"附加图标：创建桌面快捷方式（可选）。","start.desktop.s6.title":"完成并启动","start.desktop.s6.desc":"保持勾选 <strong>Launch DSH Automation Suite</strong>，点 <strong>Finish</strong>。应用窗口会直接打开，套件 profile 已经生效 —— 没有需要一直开着的控制台窗口。","start.desktop.s6.cap":"向导最后一页 —— 只想装快捷方式就取消勾选启动。","start.desktop.s7.title":"打开后是什么样","start.desktop.s7.desc":"一个 WebView2 窗口，标题条与 DeepSeek Harness 桌面版一致：左侧是 <code>Application</code> 与 <code>Edit</code> 菜单，右侧是窗口按钮，套件 preset 与右侧五个 tab 已就位。它没有地址栏，也不依赖你的浏览器。主题与语言跟随应用自身设置，见下面两张缩略图。","start.desktop.s7.cap":"安装后的壳：浅色主题、英文界面。","start.desktop.s7.cap2":"深色主题、英文界面。","start.desktop.s7.cap3":"深色主题、中文界面。","start.desktop.callout":"安装器不打包 DSH 运行时：优先复用你已装的版本，缺失时才从 <code>download.deepseek.com</code> 取官方安装包。比已验证的 0.2.1-rc.2 更新的版本只警告、不阻止；低于 0.2.1-rc.1 的版本会被拒绝，而不是被覆盖。离线机器请先装好 DSH 与 WebView2 —— 之后向导不需要网络，因为不会从 npm 取任何东西。","start.desktop.s8.title":"实际跑起来的样子","start.desktop.s8.desc":"一个进行中的会话：模型在逐个调用 TIA 工具（<code>project_status</code>、<code>workspace_describe</code>、<code>open_project</code>、<code>project_version_query</code>、<code>git_status</code>），聊天区显示它的规划与待办，右侧 <strong>Versions</strong> 面板列出最近两次提交、每个改动过的块，以及变更属于接口、代码、注释还是块属性。这是已发布的界面，不是示意图。","start.desktop.s8.cap":"进行中的会话 —— 工具调用、待办与 Versions 面板（深色壳）。","start.openness.title":"第一次调用 TIA：放行 Openness 访问","start.openness.desc":"第一次有工具碰到 TIA 时，Portal 会先过一道自己的门：弹「Openness access (0033:…)」，问是否允许 profile 下 <code>node_modules</code> 里的 <code>TiaOpennessV17Min.Controller.exe</code> 接入正在运行的实例。这个对话框来自西门子，不是套件弹的，也没有静默绕过的办法。<strong>Yes</strong> 只放行当前会话；<strong>Yes to all</strong> 还会把授权写进 V17 白名单（<code>HKLM\\SOFTWARE\\Siemens\\Automation\\Openness\\17.0\\Whitelist</code>），重建或升级之后不会再问 —— 写这一项需要以管理员权限运行 TIA。<strong>No</strong> 会让这次调用失败：重试并放行即可。","start.openness.cap":"Openness 访问确认 —— 套件控制器向运行中的 Portal 申请权限（点开看整个窗口）。","home.nav.home":"首页","home.nav.arch":"架构","home.nav.road":"路线图","home.nav.start":"开始使用","home.hero.cta":"开始使用","home.wall.eyebrow":"能力地图","home.wall.hint":"悬停查看术语","home.wall.legend":"在路线图上，尚未发布","home.dist.title":"<span class=\"tw-font-semibold\">面向工业自动化打造的 DeepSeek Harness 发行版</span>\n                    <br>\n                    <span class=\"tw-font-serif\">随心用<span style=\"white-space: nowrap\">你自己的插件</span>定制它。</span>","home.dist.lead":"这份发行版打包了几组核心插件，为 agent 补上工业自动化相关能力 —— TIA Portal 访问、工程知识图谱、Git 与 PLCSIM。","home.dist.cta":"看看架构","home.ctx.title":"与 AI 协作","home.ctx.note":"看得懂你的工程，才帮得上你的活。","home.ctx.c1.title":"读懂工程","home.ctx.c1.desc":"块被导出、交叉引用被重建、程序段被翻译、图纸被索引 —— 于是 agent 知道这个工程是怎么拼起来的，并能基于必要的上下文回答问题。","home.ctx.c2.title":"版本管理","home.ctx.c2.desc":"块指纹告诉你到底哪些块真的变了；agent 结合改动上下文替你完成提交，让版本历史保持连续，而不是一堆二进制文件。","home.ctx.c3.title":"仿真","home.ctx.c3.desc":"通过 PLCSIM Advanced 的 API 4.0，agent 可以上下电、下载、读写变量、快照与恢复 —— 于是能在运行时检验程序、评估它的真实行为，而不只是源码写了什么。","home.ctx.wide.caption":"同样够得着","home.ctx.chip1":"电气图纸","home.ctx.chip2":"变更历史","home.ctx.chip3":"技术文档","home.ctx.chip4":"硬件组态","home.ctx.chip5":"已装技能","home.ctx.wide.title":"更宽的工程上下文","home.ctx.wide.desc":"PLC 工程不只有程序。当图纸、变更历史、文档与硬件都在手边，agent 依据的是工程真实的背景 —— 能回答「这是怎么变成现在这样的」，而不只是「代码现在写了什么」。","home.ships.title":"今天能用的东西","home.ships.note":"六个族，一份 profile。状态以仓库路线图为准 —— 规划中的能力不会写成已发布。","home.ships.cta":"看组件清单","home.ships.s1.title":"TIA Portal V17 块级读写","home.ships.s1.desc":"通过 TIA Openness 读写块、变量表与工程数据 —— 46 个工具，每个工具对应一个白名单操作，该预览的地方默认 dry-run，每次写入后读回验证。","home.ships.s1.status":"部分实现","home.ships.s2.title":"工程知识图谱","home.ships.s2.desc":"导出的源文件变成可查询的图谱 —— 逐设备的块、调用、变量与 I/O —— 「谁调用了这个块」是一次查询，而不是翻文件。","home.ships.s2.status":"原型","home.ships.s3.title":"带闸门的 Git","home.ships.s3.desc":"12 个 Git 工具，破坏性操作放在显式策略后面：agent 能 diff、提交、追溯，但不能悄悄改写历史。","home.ships.s3.status":"部分实现","home.ships.s4.title":"仿真","home.ships.s4.desc":"通过 PLCSIM Advanced 的 API 4.0：上下电、RUN / STOP / 复位、变量读写、快照与恢复。","home.ships.s4.status":"原型","home.ships.s5.title":"应用里的面板","home.ships.s5.desc":"PLC 块、版本、变更、硬件与图纸面板就挂在聊天旁边 —— 模型读到的同一份状态，摆在你眼前可核对。","home.ships.s5.status":"部分实现","home.ships.s6.title":"接下来","home.ships.s6.desc":"TIA Portal V18、硬件组态、在线与下载、块比较、电缆与端子图纸 —— 规划中，不是承诺。","home.ships.s6.status":"规划中","home.faq.title":"常见问题","home.faq.q1":"这是 DeepSeek 或西门子的官方产品吗？","home.faq.a1":"不是。它是一份非官方的 DeepSeek Harness 发行版，加上我们自己的 TIA 与工程插件。DeepSeek、Siemens 与 TIA Portal 仅作事实性指称；本仓库是 MIT 许可，TIA Portal / PLCSIM 的许可证由你自行提供。","home.faq.q2":"用它需要准备什么？","home.faq.a2":"Windows 10/11 x64 与 DeepSeek Harness —— 桌面版安装器发现缺失时会自动下载 DSH。TIA 工具需要启用 Openness 的 TIA Portal V17，仿真需要带 API 4.0 的 PLCSIM Advanced，知识图谱需要 .NET 8。","home.faq.q3":"它会自己往我的工程里写东西吗？","home.faq.a3":"不会。读取是显式调用；写入也是工具调用，该预览的地方先 dry-run，全部在 TIA 事务里执行，并在报告完成前读回验证。验证不通过时事务回滚，工程保持原样。","home.faq.q4":"改动是怎么做版本管理的？","home.faq.a4":"工程源文件被导出为文本并提交进 Git。Versions 面板读取最近几次提交，逐块列出改动及其类型 —— 接口、代码、注释、属性 —— 改动是可评审的，而不是一团二进制。","home.faq.q5":"需要联网吗？","home.faq.a5":"它完全在本机运行：壳、插件与 TIA 控制器都在你的机器上。唯一的出网流量是你配置的模型 API，以及安装时的 GitHub 与 download.deepseek.com。","home.faq.q6":"现在还没有什么？","home.faq.a6":"V18 支持、硬件组态、在线与下载、块比较、电缆/端子图纸。每一项的真实状态见路线图页。","home.end.title":"装好，然后打开一个工程","home.end.note":"一个安装器、独立的 DSH home、不需要构建。装好 Portal V17，TIA 工具就能用。","home.end.cta":"开始使用","home.end.cta2":"读架构说明","home.foot.product":"产品","home.foot.arch":"架构","home.foot.road":"路线图","home.foot.start":"开始使用","home.foot.releases":"发布包","home.foot.repo":"仓库","home.foot.github":"GitHub","home.foot.readme":"README","home.foot.license":"MIT 许可","home.foot.notes":"说明","home.foot.disclaimer":"非官方项目，与 DeepSeek 及 Siemens 均无隶属关系。","home.foot.trademark":"TIA Portal 与 SIMATIC 是 Siemens AG 的商标，此处仅作事实性指称。","home.foot.copy":"© 2026 dsh-automation-suite · MIT","home.foot.checked":"最后核对 2026-11-09"}};

  var META = {"home":{"en":{"title":"dsh-automation-suite","desc":"An unofficial DeepSeek Harness distribution that gives the agent industrial-automation reach: TIA Portal V17 access, an engineering knowledge graph, Git and PLCSIM."},"zh":{"title":"dsh-automation-suite","desc":"非官方 DeepSeek Harness 发行版，为 agent 补上工业自动化能力：TIA Portal V17 访问、工程知识图谱、Git 与 PLCSIM。"}},"arch":{"en":{"title":"Architecture — dsh-automation-suite","desc":"How twelve bundles become one DSH distribution: package boundaries, plugin dependencies, and preset-scoped tools."},"zh":{"title":"架构 — dsh-automation-suite","desc":"十二个 bundle 如何组成一个 DSH 发行版：包边界、插件依赖与 preset 工具面。"}},"road":{"en":{"title":"Roadmap — dsh-automation-suite","desc":"Maturity, environment compatibility and the planned capability of the distribution."},"zh":{"title":"路线图 — dsh-automation-suite","desc":"成熟度、环境兼容性与规划中的能力。"}},"start":{"en":{"title":"Get Started — dsh-automation-suite","desc":"Prerequisites, the desktop installer walkthrough with screenshots, the other three install paths, first-run configuration and installation notes."},"zh":{"title":"开始使用 — dsh-automation-suite","desc":"环境要求、桌面版安装器的图文步骤、另外三条安装路径、首次启动与安装注意事项。"}}};

  var doc = document.documentElement;
  var page = (document.body && document.body.dataset.page) || "home";
  var slots = Array.prototype.slice.call(document.querySelectorAll("[data-block]"));
  var descMeta = document.querySelector('meta[name="description"]');
  var langBtns = document.querySelectorAll(".lang__btn");

  /* The site editor (tools/site-editor) wraps every editable text run in an HTML
     comment like <!--dsh-e12-345-->. Rewriting innerHTML throws those away, so when
     the dictionary holds exactly the text already on the page (the English case),
     leave the nodes alone and keep them editable. */
  function withoutEditMarkers(html) {
    return html.replace(/<!--dsh-e\d+-\d+-->/g, "");
  }

  function dict(lang) {    var key = lang === "zh" ? "zh" : "en";
    var base = I18N[key] || {};
    var extra = (window.ARCH_I18N && window.ARCH_I18N[key]) || {};
    var merged = {};
    for (var k in base) if (Object.prototype.hasOwnProperty.call(base, k)) merged[k] = base[k];
    for (var e in extra) if (Object.prototype.hasOwnProperty.call(extra, e)) merged[e] = extra[e];
    return merged;
  }

  function apply(lang) {
    var key = lang === "zh" ? "zh" : "en";
    var blocks = dict(key);
    slots.forEach(function (el) {
      var id = el.getAttribute("data-block");
      if (!Object.prototype.hasOwnProperty.call(blocks, id)) return;
      /* With the editor attached, the English page text is the source of truth:
         the server re-injects markers after a save, so leaving the nodes alone is
         what makes an edit stick instead of being overwritten by the dictionary. */
      if (key === "en" && /<!--dsh-e\d+-\d+-->/.test(el.innerHTML)) return;
      if (withoutEditMarkers(el.innerHTML) === blocks[id]) return;
      el.innerHTML = blocks[id];
    });
    if (typeof window.renderArch === "function") window.renderArch(key);
    doc.lang = key === "zh" ? "zh-CN" : "en";
    var m = (META[page] || {})[key] || {};
    if (m.title) document.title = m.title;
    if (m.desc && descMeta) descMeta.setAttribute("content", m.desc);
    langBtns.forEach(function (btn) {
      var on = btn.dataset.lang === key;
      btn.classList.toggle("is-on", on);
      btn.setAttribute("aria-pressed", on ? "true" : "false");
    });
    try { localStorage.setItem(KEY, key); } catch (e) { /* private mode */ }
    /* Pages with generated content (the home page's capability wall) re-render on this. */
    try {
      document.dispatchEvent(new CustomEvent("das:langchange", { detail: { lang: key } }));
    } catch (e) { /* older engines */ }
  }

  var stored = null;
  try { stored = localStorage.getItem(KEY); } catch (e) { /* ignore */ }
  apply(stored === "zh" ? "zh" : "en");

  langBtns.forEach(function (btn) {
    btn.addEventListener("click", function () {
      apply(btn.dataset.lang === "zh" ? "zh" : "en");
    });
  });

  var copyBtns = document.querySelectorAll(".copy");
  Array.prototype.forEach.call(copyBtns, function (copyBtn) {
    var copyLabel = copyBtn.querySelector("[data-block]");
    copyBtn.addEventListener("click", function () {
      var target = document.getElementById(copyBtn.dataset.copyTarget || "");
      if (!target) return;
      var text = target.textContent.split("\n").map(function (line) {
        return line.replace(/^\s*\$\s?/, "");
      }).join("\n").trim();
      var done = function () {
        if (copyLabel) copyLabel.textContent = dict(doc.lang === "zh-CN" ? "zh" : "en")["shared.copied"] || "Copied";
        copyBtn.classList.add("is-done");
        setTimeout(function () {
          if (copyLabel) copyLabel.textContent = dict(doc.lang === "zh-CN" ? "zh" : "en")["shared.copy"] || "Copy";
          copyBtn.classList.remove("is-done");
        }, 1600);
      };
      if (navigator.clipboard && navigator.clipboard.writeText) {
        navigator.clipboard.writeText(text).then(done, done);
      } else {
        var ta = document.createElement("textarea");
        ta.value = text;
        ta.style.position = "fixed";
        ta.style.opacity = "0";
        document.body.appendChild(ta);
        ta.select();
        try { document.execCommand("copy"); } catch (e) { /* ignore */ }
        document.body.removeChild(ta);
        done();
      }
    });
  });
})();
